import{_ as t,o,c as u,ag as q}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第65章 今天有雨","description":"","frontmatter":{},"headers":[],"relativePath":"第65章_今天有雨.md","filePath":"第65章_今天有雨.md"}'),e={name:"第65章_今天有雨.md"};function a(_,p,r,n,s,c){return o(),u("div",null,[...p[0]||(p[0]=[q('<h1 id="第65章-今天有雨" tabindex="-1">第65章 今天有雨 <a class="header-anchor" href="#第65章-今天有雨" aria-label="Permalink to &quot;第65章 今天有雨&quot;">​</a></h1><p>&quot;记得删&quot;这句话，是我们每天的最后一句。</p><p>高一那年她教过我删。</p><p>那次我嘴上说好，转头把东西另存了一份。</p><p>六年以后，这句话变成了我们两个的晚安。</p><p>我们不说晚安。</p><p>我们说&quot;记得删&quot;。</p><p>一开始是她说的，每天晚上说完话，她发三个字。</p><p>我说，好。</p><p>她说，你删了吗。</p><p>我说，删了。</p><p>她说，那你删吧。</p><p>后来变成我说的。</p><p>我不知道我什么时候开始说的。</p><p>大概是有一天夜里，我算出来她那天发的话里有两句提到了&quot;我妈在客厅&quot;。</p><p>那天我说了一句&quot;记得删&quot;。</p><p>她隔了一会儿，回：你怎么知道我要说这个。</p><p>我说，因为你今天讲了两次客厅。</p><p>她说，哦。</p><p>她说，你比我小心。</p><p>从那天起，那三个字是我们两个人轮流说的。</p><p>谁先说都行，但每天必须有人说。</p><p>有一天没人说。</p><p>那是三月里的一天，我发完最后一条就睡着了。</p><p>第二天早上我七点起来，看见她凌晨留的一句。</p><p>她说，你今天没跟我说记得删。</p><p>我说，我睡着了。</p><p>她说，我知道你睡着了。</p><p>我说，那今天没什么要删的。</p><p>她说，你有。</p><p>我说，我没什么。</p><p>她说，你昨天最后一条写了二百多字。</p><p>她说，你写那么长，你要是被人看见，你解释不了。</p><p>我说，谁会看我手机。</p><p>她说，我不知道。</p><p>她说，我就是不知道才要删。</p><p>我看着这一句，坐在那里很久。</p><p>我说，好，我以后说。</p><p>她说，你今天说。</p><p>我说，记得删。</p><p>她说，好。</p><p>我们还有一个暗号。</p><p>这个暗号是她发明的。</p><p>发明原因很实在：她那边的生活里有太多人会瞟一眼她的屏幕。</p><p>地铁上、教室里、吃饭的时候。</p><p>她需要一个说法，能让我立刻停止发东西，而且这个说法在别人眼里毫无意义。</p><p>她说，以后我说&quot;今天有雨&quot;，就是你现在别发。</p><p>我说，为什么是有雨。</p><p>她说，因为下雨很无聊，没有人会多看一眼。</p><p>我说，好。</p><p>她说，你也不要问为什么，你一问就像真有人在你旁边。</p><p>我说，明白了。</p><p>从那以后，&quot;今天有雨&quot;就是我们的停。</p><p>我那边要是看到这四个字，我立刻停手。</p><p>我会把想发的话删掉，然后回一句很没用的话，比如&quot;那你先忙&quot;。</p><p>这句话演变得很快。</p><p>后来她开始用它表示别的意思。</p><p>有雨，是我妈在。</p><p>有雨，我在上课。</p><p>有雨，我在哭。</p><p>这三种她也不解释，我也不问。</p><p>我根据她后面多久回来判断是哪一种。</p><p>十分钟回来的，是上课。</p><p>半天回来的，是她妈。</p><p>夜里才回来的，是第三种。</p><p>那年四月有一天，她说，今天有雨。</p><p>我停了。</p><p>那天我正好拍到了一样东西。</p><p>我们这边下了今年最大的一场雨，宿舍楼下面那条路淹了，一辆自行车躺在水里，水从它脚踏板那儿往上冒泡。</p><p>我那天拍得特别高兴。</p><p>我拿起来想发，看见了&quot;今天有雨&quot;。</p><p>我把照片留着。</p><p>我回：那你先忙。</p><p>晚上八点，她回来了。</p><p>她说，刚才在超市。</p><p>我说，嗯。</p><p>她说，你怎么不高兴。</p><p>我说，没有。</p><p>她说，你今天肯定发了什么，我回来的时候上面一条都没有。</p><p>我说，我今天拍了一场雨。</p><p>她说，那你现在发。</p><p>我发了。</p><p>她看完回了一句。</p><p>她说，我这里今天没有下雨。</p><p>我说，我知道。</p><p>她说，你知道了你怎么不说话。</p><p>我说，你说有雨，我就得停。</p><p>她说，你这个人。</p><p>她说，以后我说有雨，你要先想一下是不是真的。</p><p>我说，我怎么想。</p><p>她说，你看看你那边。</p><p>我说，你那边和我这边不一样。</p><p>她说，对。</p><p>她说，所以以后我说&quot;有雨&quot;的时候，我说清楚。</p><p>那天以后她真的开始区分。</p><p>她说&quot;我这边有雨&quot;，我就继续。</p><p>她说&quot;有雨&quot;，我就停。</p><p>多了一个字，安全了一整年。</p><p>五月，出了一件事。</p><p>那天她发：有雨。</p><p>我停了。</p><p>停了两个小时，她回来，说她在办一件事。</p><p>我那天心情不好，我多问了一句。</p><p>我说，你那边今天到底下没下雨。</p><p>她隔了一会儿。</p><p>她说，下了一点。</p><p>我的心一下沉下去。</p><p>因为我不知道这一次她说的是哪一种。</p><p>如果她那边真在下，那&quot;有雨&quot;这两个字今天既是暗号又是天气。</p><p>那她那天到底是让我停，还是只是在讲今天。</p><p>我说，那你今天是有事，还是在讲天气。</p><p>她回：都有。</p><p>我说，那我怎么分。</p><p>她不说话了。</p><p>过了很久，她发了一句。</p><p>她说，我分不了了。</p><p>她说，我发现这个话我们用了半年，现在它已经不是我们的了。</p><p>她说，我说&quot;有雨&quot;的时候，我自己要想一下我是什么意思。</p><p>她说，那我以后不说了。</p><p>我说，那你怎么办。</p><p>她说，我就发&quot;在忙&quot;。</p><p>我说，在忙不行。</p><p>她说，为什么。</p><p>我说，在忙所有人都能看懂，你身边的人一看就知道你在躲。</p><p>她说，那就没办法了。</p><p>她说，你说一个。</p><p>我想了整整十分钟。</p><p>我说，你说&quot;我吃了&quot;。</p><p>她说，什么？</p><p>我说，你说&quot;我吃了&quot;，我就停。你说&quot;我吃了面&quot;，我可以继续。</p><p>她笑了。</p><p>她说，你这个人真恶心，你让我每天跟你说我吃了。</p><p>我说，这样安全。</p><p>她说，行。</p><p>她说，那我今晚吃什么。</p><p>我说，你想吃什么。</p><p>她说，我不想吃，我刚才只是想说，我今天很难受。</p><p>我说，那你难受的时候，你就说&quot;我吃了&quot;。</p><p>她说，好。</p><p>那晚最后是我说的&quot;记得删&quot;。</p><p>我说完，她回：删了。</p><p>我回：我也删了。</p><p>那天夜里我在本子上抄下这两句的时候，停了一下。</p><p>我知道我们两个说的都是假话。</p><p>我知道她说假话是因为她不能不留。</p><p>她留的是命，不是东西。</p><p>我知道我说假话是因为我不能说我没删。</p><p>我们把这句假话互道了三年。</p><p>三年以后，她给我发来一个文件夹。</p><p>那天她附带了一句话。</p><p>她说，我说过我会删的。</p><p>那个文件夹里的东西，一条都没删。</p>',152)])])}const l=t(e,[["render",a]]);export{d as __pageData,l as default};
